import{_ as r,c as o,ag as t,o as e}from"./chunks/framework.-a8jReyC.js";const m=JSON.parse('{"title":"Planos e Preços","description":"","frontmatter":{"title":"Planos e Preços"},"headers":[],"relativePath":"plans-and-pricing.md","filePath":"plans-and-pricing.md"}'),s={name:"plans-and-pricing.md"};function i(l,a,n,d,c,p){return e(),o("div",null,a[0]||(a[0]=[t('<h1 id="planos-e-precos-💳" tabindex="-1"><strong>Planos e Preços 💳</strong> <a class="header-anchor" href="#planos-e-precos-💳" aria-label="Permalink to &quot;**Planos e Preços 💳**&quot;">​</a></h1><p>O FlyCash oferece planos para atender às necessidades de quem deseja controlar suas finanças pessoais de forma eficiente. Confira os detalhes de cada plano e escolha o que melhor se adapta a você.</p><hr><h3 id="controle-inicial-gratis-👛" tabindex="-1"><strong>Controle Inicial (Grátis) 👛</strong> <a class="header-anchor" href="#controle-inicial-gratis-👛" aria-label="Permalink to &quot;**Controle Inicial (Grátis) 👛**&quot;">​</a></h3><p>O plano gratuito é ideal para quem quer começar a organizar suas finanças sem compromisso. Ele oferece recursos básicos para gerenciar seu dinheiro de forma simples e prática.</p><h4 id="recursos-incluidos" tabindex="-1"><strong>Recursos Incluídos:</strong> <a class="header-anchor" href="#recursos-incluidos" aria-label="Permalink to &quot;**Recursos Incluídos:**&quot;">​</a></h4><ul><li><p><strong>Registro manual de transações:</strong><br> Anote gastos e receitas do dia a dia.</p></li><li><p><strong>Grupos e Categorias:</strong><br> Organize suas transações utilizando grupos e categorias (exemplo: Despesas, Receitas, Investimentos).</p></li><li><p><strong>Visualização de Saldos:</strong><br> Consulte os saldos de cada grupo e categoria com base nas transações registradas.</p></li><li><p><strong>Parcelas e recorrências:</strong><br> Crie transações recorrentes e acompanhe parcelas (contam no limite mensal).</p></li></ul><h4 id="limitacoes" tabindex="-1"><strong>Limitações:</strong> <a class="header-anchor" href="#limitacoes" aria-label="Permalink to &quot;**Limitações:**&quot;">​</a></h4><ul><li>Até <strong>10 categorias</strong>.</li><li>Até <strong>3 saldos personalizados</strong>.</li><li>Até <strong>100 transações por mês</strong>.</li><li>Até <strong>1 importação de fatura por mês</strong>.</li></ul><h4 id="ideal-para" tabindex="-1"><strong>Ideal Para:</strong> <a class="header-anchor" href="#ideal-para" aria-label="Permalink to &quot;**Ideal Para:**&quot;">​</a></h4><ul><li>Usuários que desejam experimentar a ferramenta sem compromisso e precisam de funcionalidades básicas de controle financeiro.</li></ul><hr><h3 id="essencial-r-6-90-mes-💡" tabindex="-1"><strong>Essencial (R$ 6,90/mês) 💡</strong> <a class="header-anchor" href="#essencial-r-6-90-mes-💡" aria-label="Permalink to &quot;**Essencial (R$ 6,90/mês) 💡**&quot;">​</a></h3><p>O plano Essencial é para quem quer organizar as finanças <strong>sem limites</strong>, com importação de faturas e recorrências à vontade.</p><h4 id="recursos-incluidos-1" tabindex="-1"><strong>Recursos Incluídos:</strong> <a class="header-anchor" href="#recursos-incluidos-1" aria-label="Permalink to &quot;**Recursos Incluídos:**&quot;">​</a></h4><ul><li><p><strong>Tudo do Plano Grátis, sem limites:</strong></p><ul><li>Categorias, saldos e transações <strong>ilimitados</strong>.</li><li><strong>Importação de faturas</strong> (PDF/OFX) ilimitada.</li><li>Parcelas e recorrências ilimitadas.</li></ul></li><li><p><strong>Análise por categoria:</strong><br> Totais e principais transações por categoria.</p></li><li><p><strong>Lembretes por e-mail.</strong></p></li></ul><h4 id="ideal-para-1" tabindex="-1"><strong>Ideal Para:</strong> <a class="header-anchor" href="#ideal-para-1" aria-label="Permalink to &quot;**Ideal Para:**&quot;">​</a></h4><ul><li>Quem usa o FlyCash com frequência e quer registrar/importar sem se preocupar com limites.</li></ul><hr><h3 id="equilibrio-total-r-14-90-mes-💎" tabindex="-1"><strong>Equilíbrio Total (R$ 14,90/mês) 💎</strong> <a class="header-anchor" href="#equilibrio-total-r-14-90-mes-💎" aria-label="Permalink to &quot;**Equilíbrio Total (R$ 14,90/mês) 💎**&quot;">​</a></h3><p>O plano Equilíbrio Total oferece a gama completa de recursos para usuários que buscam controle e análise avançada.</p><h4 id="recursos-incluidos-2" tabindex="-1"><strong>Recursos Incluídos:</strong> <a class="header-anchor" href="#recursos-incluidos-2" aria-label="Permalink to &quot;**Recursos Incluídos:**&quot;">​</a></h4><ul><li><p><strong>Tudo do Plano Essencial, sem limites.</strong></p></li><li><p><strong>Relatórios avançados:</strong><br> Análise por categoria com comparativo e variação entre períodos.</p></li><li><p><strong>Exportação XLSX:</strong><br> Exporte transações e análises para Excel.</p></li><li><p><strong>Suporte prioritário.</strong></p></li></ul><h4 id="ideal-para-2" tabindex="-1"><strong>Ideal Para:</strong> <a class="header-anchor" href="#ideal-para-2" aria-label="Permalink to &quot;**Ideal Para:**&quot;">​</a></h4><ul><li>Usuários que desejam um controle financeiro completo e análises aprofundadas.</li></ul><hr><h3 id="precos" tabindex="-1"><strong>Preços</strong> <a class="header-anchor" href="#precos" aria-label="Permalink to &quot;**Preços**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Plano</th><th>Valor Mensal (R$)</th></tr></thead><tbody><tr><td><strong>Controle Inicial</strong></td><td>R$ 0,00</td></tr><tr><td><strong>Essencial</strong></td><td>R$ 6,90</td></tr><tr><td><strong>Equilíbrio Total</strong></td><td>R$ 14,90</td></tr></tbody></table><p><em>Todos os valores estão sujeitos a alterações. Consulte sempre a página oficial para os preços mais atualizados.</em></p><hr><h3 id="comparacao-de-planos" tabindex="-1"><strong>Comparação de Planos</strong> <a class="header-anchor" href="#comparacao-de-planos" aria-label="Permalink to &quot;**Comparação de Planos**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recurso / Plano</th><th>Controle Inicial</th><th>Essencial</th><th>Equilíbrio Total</th></tr></thead><tbody><tr><td>Registro manual de transações</td><td>✔️ (100/mês)</td><td>✔️ (ilimitado)</td><td>✔️ (ilimitado)</td></tr><tr><td>Grupos e Categorias</td><td>✔️ (10 categorias)</td><td>✔️ (ilimitado)</td><td>✔️ (ilimitado)</td></tr><tr><td>Saldos Personalizados</td><td>✔️ (3)</td><td>✔️ (ilimitado)</td><td>✔️ (ilimitado)</td></tr><tr><td>Parcelas e Recorrências</td><td>✔️ (contam no limite)</td><td>✔️ (ilimitado)</td><td>✔️ (ilimitado)</td></tr><tr><td>Importação de Faturas (PDF/OFX)</td><td>✔️ (1/mês)</td><td>✔️ (ilimitado)</td><td>✔️ (ilimitado)</td></tr><tr><td>Análise por Categoria</td><td>🔒</td><td>✔️</td><td>✔️</td></tr><tr><td>Relatórios Avançados</td><td>🔒</td><td>🔒</td><td>✔️</td></tr><tr><td>Exportação XLSX</td><td>🔒</td><td>🔒</td><td>✔️</td></tr><tr><td>Suporte Prioritário</td><td>🔒</td><td>🔒</td><td>✔️</td></tr></tbody></table><hr><h3 id="como-escolher-o-plano-certo-para-voce" tabindex="-1"><strong>Como Escolher o Plano Certo para Você?</strong> <a class="header-anchor" href="#como-escolher-o-plano-certo-para-voce" aria-label="Permalink to &quot;**Como Escolher o Plano Certo para Você?**&quot;">​</a></h3><ul><li><strong>Controle Inicial:</strong> está começando e quer experimentar sem compromisso.</li><li><strong>Essencial:</strong> usa com frequência e quer registrar/importar sem limites.</li><li><strong>Equilíbrio Total:</strong> precisa de análises avançadas, exportação e suporte prioritário.</li></ul><hr><p>Escolha o plano que mais se adapta às suas necessidades e comece a melhorar seu controle financeiro agora mesmo! 💰</p>',37)]))}const g=r(s,[["render",i]]);export{m as __pageData,g as default};
